<?php
declare(strict_types=1);require_once dirname(__DIR__).'/config/bootstrap.php';require_permission('inventory.view');$productId=(int)($_GET['product']??0);$p=db()->prepare('SELECT p.id,p.name,p.sku,p.current_stock,p.minimum_stock,p.average_cost,u.short_name FROM products p INNER JOIN units u ON u.id=p.unit_id WHERE p.id=:id');$p->execute([':id'=>$productId]);$product=$p->fetch();if(!$product){flash('error','Product not found.');redirect('inventory/index');}$m=db()->prepare('SELECT sm.*,usr.full_name FROM stock_movements sm INNER JOIN users usr ON usr.id=sm.created_by WHERE sm.product_id=:id ORDER BY sm.id DESC LIMIT 500');$m->execute([':id'=>$productId]);$rows=$m->fetchAll();$pageTitle='Stock History';$pageStyles=['admin.css','commerce.css'];require BASE_PATH.'/includes/header.php';require BASE_PATH.'/includes/sidebar.php';?>
<div class="app-main"><?php require BASE_PATH.'/includes/navbar.php';?><main class="content"><div class="page-toolbar"><div><a class="back-link" href="<?=e(app_url('inventory/index'))?>">← Inventory</a><h2><?=e($product['name'])?> stock history</h2><p><?=e($product['sku'])?> · current <?=e(format_quantity($product['current_stock']))?> <?=e($product['short_name'])?></p></div><?php if(user_can('inventory.adjust')):?><a class="button button--primary" href="<?=e(app_url('inventory/stock_adjustment?product='.$productId))?>">Adjust stock</a><?php endif;?></div><section class="panel-card table-panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>Date</th><th>Type</th><th>Change</th><th>Before</th><th>After</th><th>Unit cost</th><th>Reference</th><th>Reason</th><th>User</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="9"><div class="empty-state"><strong>No stock history</strong></div></td></tr><?php else:foreach($rows as$r):?><tr><td><?=e(format_datetime($r['created_at']))?></td><td><?=e(ucwords(str_replace('_',' ',$r['movement_type'])))?></td><td class="<?=((float)$r['quantity_change']>=0?'text-success':'text-danger')?>"><?=((float)$r['quantity_change']>=0?'+':'')?><?=e(format_quantity($r['quantity_change']))?></td><td><?=e(format_quantity($r['stock_before']))?></td><td><?=e(format_quantity($r['stock_after']))?></td><td><?=e(money($r['unit_cost']))?></td><td><?=e($r['reference_no']?:'—')?></td><td><?=e($r['reason']?:'—')?></td><td><?=e($r['full_name'])?></td></tr><?php endforeach;endif;?></tbody></table></div></section></main></div><?php require BASE_PATH.'/includes/footer.php';?>
